using System;using System.IO;using System.Linq;using System.Text;using System.Web.Script.Serialization;
class LocalAuthorizationTests {
 static int checks,failures;static void Check(bool ok,string name){checks++;if(!ok)failures++;Console.WriteLine((ok?"PASS ":"FAIL ")+name);}
 [STAThread]static int Main(string[] args){var json=new JavaScriptSerializer();string root=Path.Combine(args[0],"local-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{
 string exe=Path.Combine(root,"probe.exe");File.Copy(Path.Combine(args[0],"..","v5.20.2-security","BenignQuotaProbe.exe"),exe);string data=Path.Combine(root,"profile");var trust=new QuotaExecutionTrust(data);var id=trust.Inspect(exe,root);trust.Approve(id);string record=Directory.GetFiles(data,"quota-program-trust.*").Single();Check(!Encoding.UTF8.GetString(File.ReadAllBytes(record)).Contains("probe.exe"),"saved authorization does not expose plaintext executable path");using(new QuotaExecutionTrust(data).OpenVerified(exe,root)){Check(true,"same user and computer retain authorization after restart");}
 string legacy=Path.Combine(root,"legacy");Directory.CreateDirectory(legacy);File.WriteAllText(Path.Combine(legacy,"quota-program-trust.json"),json.Serialize(id));bool blocked=false;try{using(new QuotaExecutionTrust(legacy).OpenVerified(exe,root)){}}catch(IOException){blocked=true;}Check(blocked,"unbound legacy authorization cannot silently grant execution");
 var saved=File.ReadAllBytes(record);var envelope=json.Deserialize<QuotaProgramIdentity>(Encoding.UTF8.GetString(LocalProtection.Unprotect(saved)));envelope.Machine="other-machine";File.WriteAllBytes(record,LocalProtection.Protect(Encoding.UTF8.GetBytes(json.Serialize(envelope))));blocked=false;try{using(trust.OpenVerified(exe,root)){}}catch(IOException){blocked=true;}Check(blocked,"record bound to another machine is rejected");envelope.Machine=LocalProtection.Machine;envelope.User="other-user";File.WriteAllBytes(record,LocalProtection.Protect(Encoding.UTF8.GetBytes(json.Serialize(envelope))));blocked=false;try{using(trust.OpenVerified(exe,root)){}}catch(IOException){blocked=true;}Check(blocked,"record bound to another Windows user is rejected");File.WriteAllBytes(record,saved);
 var bytes=File.ReadAllBytes(record);bytes[bytes.Length-1]^=127;File.WriteAllBytes(record,bytes);blocked=false;try{using(trust.OpenVerified(exe,root)){}}catch(IOException){blocked=true;}Check(blocked,"tampered local authorization requires confirmation again");
 }catch(Exception e){failures++;Console.WriteLine(e);}File.WriteAllText(Path.Combine(args[0],"local-authorization-results.json"),json.Serialize(new{checks,failures}));return failures==0?0:1;}
}
